@Override
public void startElement(String uri, String localName, String qName, Attributes atts) throws SAXException {
    String uc = (qName == null) ? "" : qName.toUpperCase(Locale.ENGLISH);
    if (uc.equals(STYLE)) {
        styleDepth++;
    }
    if (uc.equals(SCRIPT)) {
        scriptDepth++;
    }
}
